// Site content. Media is referenced by slug (see src/data/media.json, generated by the
// asset pipeline from assets/raw).

export type Piece = { slug: string; caption?: string };
export type Brand = {
  id: string;
  name: string;      // as shown on the sketchbook cover
  mono: string;      // short monogram for the cover "logo"
  sub: string;       // small line under the name
  blurb: string;     // inside-cover copy
  cover?: string;    // cover colour
  pieces: Piece[];
};

const p = (prefix: string, ids: (string | [string, string])[]): Piece[] =>
  ids.map((x) => (Array.isArray(x) ? { slug: `${prefix}${x[0]}`, caption: x[1] } : { slug: `${prefix}${x}` }));

